The bug is a data race: `c.count++` is not atomic, so concurrent goroutines can read the same value, increment it, and write back the same result, losing updates. `GetCount` also reads `c.count` without synchronization.

Fix: protect `count` with a `sync.Mutex` (or use `atomic.Int64`).

<solution language="go" verdict="fix">
package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    mu    sync.Mutex
    count int
}

func (c *Counter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.count++
}

func (c *Counter) GetCount() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.count
}

func main() {
    counter := &Counter{}
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter.Increment()
        }()
    }

    wg.Wait()
    fmt.Println("Final count:", counter.GetCount())
}
</solution>

